vec3 bg = vec3(0.3, 0.3, 0.3);
vec3 white = vec3(1.0, 1.0, 1.0);
vec3 red = vec3(1.0, 0.0, 0.0);
vec3 green = vec3(0.0, 1.0, 0.0);
vec3 blue = vec3(0.0, 0.0, 1.0);
vec3 black = vec3(0.0, 0.0, 0.0);

struct Material {
    vec3 ambient;
    vec3 diffuse;
    vec3 specular;
    float roughness;
};

Material materials[2] = Material[2](
    //chrome
    Material(vec3(0.0215, 0.1745, 0.0215), vec3(0.07568, 0.61424, 0.07568), vec3(0.633, 0.727811, 0.633), 0.4),
    // ruby
    Material(vec3(0.1745, 0.01175, 0.01175), vec3(0.61424, 0.04136,	0.04136), vec3(0.727811, 0.626959, 0.626959),0.6)
);

Material getMaterial(int i) {
    return materials[i];
}



const int SPHERES = 2;
const float PI = 22.0 / 7.0; 


float angleVec(vec3 a, vec3 b) {
    return dot(a, b) / (length(a) * length(b)); 
}

float angleVecRad(vec3 a, vec3 b) {
    return acos(angleVec(a, b)); 
}

struct Ray {
    vec3 origin;
    vec3 dir;
};

Ray newRay(vec3 origin, vec2 uv) {
    vec3 rd = normalize(vec3(vec2(uv), -1.0) - origin);
    return Ray(origin, rd);
}

struct Light {
    vec3 point;
    vec3 color;
};

Light makeLight(vec3 c, float r, vec3 color) {
    vec3 pos = c + r * vec3(sin(iTime), 0.0, cos(iTime));
    return Light(pos, color);
    //return Light(vec3(0.0, 0.0, -1.0), color);
}

struct Sphere {
    vec3 center;
    float radius;
    int matIdx;
    vec3 color;
};

struct Hit {
    bool exists;
    vec3 point;
    float lambda;
    vec3 incidence;
    vec3 norm;
    int matIdx;
    vec3 color;
};

Hit newHit() {
    return Hit(false, vec3(0.0), 0.0, vec3(0.0), vec3(0.0), -1, vec3(0.0));
}

float shade(Hit hit, Light light) {
    vec3 toLight = normalize(light.point - hit.point);
    return 1.0 - angleVec(toLight, hit.norm);
}

float spec(Hit hit, Light light) {
    vec3 toLight = normalize(light.point - hit.point);
    float a = angleVecRad(toLight, hit.norm);
    if (a <= PI * 0.1) {
        return 1.0 - a * 2.0 / PI;
    } else {
        return 0.0;
    }
}

float dim(Hit hit, Light light) {
    vec3 dir = normalize(light.point - hit.point); 
    return 1.0 + angleVec(dir, hit.norm);// * getMaterial(hit.matIdx).ambient.x;
}

Hit hit_sphere(Sphere s, Ray ray) {

    vec3 v = ray.origin - s.center;
    float a = dot(ray.dir, ray.dir);
    float b = 2.0 * dot(ray.dir, v);
    float c = dot(v, v) - pow(s.radius, 2.0);

    float d = b * b - 4.0 * a * c;

    if (d >= 0.0) {
        float pos = (-b + sqrt(d)) / (2.0 * a);
        float neg = (-b - sqrt(d)) / (2.0 * a);
        float l = neg < 1e-6 ? pos : neg;
        vec3 q = ray.origin + l * ray.dir;
        vec3 norm = normalize(q - s.center);
        return  Hit(true, q, l, ray.dir, norm, s.matIdx, s.color);
     }
     return newHit();
}

Hit selfHit_sphere(Sphere s, Hit hit, Light light) {
    vec3 dir = normalize(light.point - hit.point);
    vec3 norm = hit.point - s.center;
    Ray ray = Ray(hit.point, dir);
    ray.origin += ray.dir * 1e-6;
    if (dot(dir, norm) <= 0.0) {
        return hit_sphere(s, ray);
    } else {
       return newHit();
    }
}

Hit otherHit_sphere(int index, Sphere[SPHERES] spheres, Hit h) {
    Sphere s = spheres[index];
    Ray ray = Ray(h.point, -reflect(h.incidence, h.norm));
    ray.origin += 1e-6 * ray.dir;
    Hit current = newHit();
    for (int i = 0; i < SPHERES; i++) {
        if (SPHERES != index) {
            Hit hit = hit_sphere(spheres[i], ray);
            if (hit.exists && hit.lambda < current.lambda) {
                current = hit;
            }
        }
    }
    return current;
}

vec3 getMatColor(Hit hit, Light light) {

    vec3 lightDir = normalize(light.point - hit.point);
    Material mat = materials[hit.matIdx];
    vec3 normal = hit.norm;
    vec3 dir = -hit.incidence;

    vec3 H = normalize(lightDir + dir);
    vec3 amb = mat.ambient;

    float diff = max(dot(normal, lightDir), 0.0);
    vec3 diffuse = mat.diffuse * diff;

    float spec = pow(max(dot(normal, H), 0.0), 1.0 / mat.roughness);
    vec3 specular = mat.specular * spec;

    return amb + diffuse + specular;
}

vec3 getMatColorIdx(Hit hit, Light light) {
    return getMatColor(hit, light);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= aspect;

    //Light light = makeLight(vec3(0.0), 1.5, 
    //    0.5 + 0.5 * vec3(sin(iTime), sin(iTime + PI * 0.5), -sin(iTime)));
    Light light = makeLight(vec3(0.0), 2.5, white);
    vec3 col = bg;

    Ray ray = newRay(vec3(0.0, 0.0, -2.0), uv);
    Sphere sphere1 = Sphere(vec3(sin(iTime), cos(iTime) * 0.5, 0.0), 0.4, 0, white);
    Sphere sphere2 = Sphere(vec3(sin(iTime + PI), cos(iTime) * -0.5, 0.0), 0.4, 1, white);
    Sphere spheres[SPHERES] = Sphere[](sphere1, sphere2);

    for (int i = 0; i < SPHERES; i++) {
        Hit hit = hit_sphere(spheres[i], ray);
        if (hit.exists) {
            float shaded = shade(hit, light);
            Hit selfHit = selfHit_sphere(spheres[i], hit, light);
            Hit otherHit = otherHit_sphere(i, spheres, hit);
            if (selfHit.exists) {
                if (otherHit.exists) {
                    float otherShaded = shade(otherHit, light);
                    col = getMatColorIdx(otherHit, light) * dim(otherHit,light) * otherHit.color; 
                } else {
                    col =  getMatColorIdx(hit, light) * dim(hit, light) * hit.color;
                }
            } else {
                float specular = spec(hit, light);
                if (otherHit.exists) {
                    float otherShaded = shade(otherHit, light);
                    col = getMatColorIdx(otherHit, light) * otherHit.color;
                } else {
                    col = getMatColorIdx(hit, light) * hit.color;
                }
            }
        }
    }

    fragColor = vec4(col, 1.0);

}
